    ('0b82d79d-e2d2-48c3-bb40-1e09e1f686b0', ARRAY['2. 적절한 표현, 정확한 읽기', '(1) 피동 표현과 인용 표현']::TEXT[], '#21 평가문제집 대조 70.5/5'),
    ('306eafd7-aeb7-41e3-b104-818df57b36d9', ARRAY['2. 적절한 표현, 정확한 읽기', '(1) 피동 표현과 인용 표현']::TEXT[], '#22 평가문제집 대조 13.5/0.5'),
    ('e25fa651-c613-4490-850c-72271272a749', ARRAY['2. 적절한 표현, 정확한 읽기', '(1) 피동 표현과 인용 표현']::TEXT[], '#23 평가문제집 대조 238.2/4.5'),
    ('d2345e45-144d-4487-b5ff-ebc8fa44bc0e', ARRAY['2. 적절한 표현, 정확한 읽기', '(1) 피동 표현과 인용 표현']::TEXT[], '#24 평가문제집 대조 13/1'),
    ('10aa2e97-f986-4c36-9b67-e9c3c28b9b56', ARRAY['2. 적절한 표현, 정확한 읽기', '(1) 피동 표현과 인용 표현']::TEXT[], '#25 총괄 판정'),
    ('a54f6997-94ee-43c6-acd7-2386b9d19c85', ARRAY['2. 적절한 표현, 정확한 읽기', '(2) 점검·조정하며 읽기']::TEXT[], '#26 평가문제집 대조 1113.5/1.5'),
    ('e0c27312-ba58-4e86-870f-5a04fb16fb11', ARRAY['2. 적절한 표현, 정확한 읽기', '(2) 점검·조정하며 읽기']::TEXT[], '#27 평가문제집 대조 1143/3'),
    ('82e8eac3-8d54-470a-be40-6540c774bcf8', ARRAY['2. 적절한 표현, 정확한 읽기', '(2) 점검·조정하며 읽기']::TEXT[], '#28 평가문제집 대조 1388/3');

  -- 1) 없는 문항 id
  SELECT count(*) INTO v_missing FROM unit_fix f WHERE NOT EXISTS (SELECT 1 FROM problems p WHERE p.id = f.id);
  IF v_missing > 0 THEN
    RAISE EXCEPTION '문항 id % 개가 DB 에 없습니다 — 목록을 다시 만들 것', v_missing;
  END IF;

  -- 2) 마스터 대조: 출처의 교과서·학년(또는 학년 구분 없음)에 그 대단원·소단원이 글자 그대로 있어야 한다
  SELECT count(*) INTO v_bad
  FROM unit_fix f JOIN problems p ON p.id = f.id JOIN problem_sources s ON s.id = p.source_id
  WHERE NOT EXISTS (
    SELECT 1 FROM major_chapters mc
    JOIN publishers pb ON pb.id = mc.publisher_id
    LEFT JOIN sub_chapters sc ON sc.major_chapter_id = mc.id
    WHERE pb.name = s.textbook AND mc.grade IN (s.grade, '') AND mc.name = f.unit_path[1]
      AND (cardinality(f.unit_path) = 1 OR sc.name = f.unit_path[2]));
  IF v_bad > 0 THEN
    RAISE EXCEPTION '마스터에 없는 단원 경로 % 개 — 카테고리 관리 이름이 바뀌었는지 볼 것', v_bad;
  END IF;

  -- 3) 지금 단원이 다른 값이면 덮지 않고 알린다
  SELECT count(*) FILTER (WHERE p.unit_path = f.unit_path), count(*) FILTER (WHERE p.unit_path <> '{}' AND p.unit_path <> f.unit_path)
    INTO v_same, v_other
  FROM unit_fix f JOIN problems p ON p.id = f.id;
  FOR r IN SELECT p.id, p.unit_path AS now_path, f.unit_path AS want FROM unit_fix f JOIN problems p ON p.id = f.id
           WHERE p.unit_path <> '{}' AND p.unit_path <> f.unit_path LOOP
    RAISE NOTICE '손으로 붙인 단원이 있어 건너뜀: % 지금=% 판정=%', r.id, r.now_path, r.want;
  END LOOP;

  UPDATE problems p SET unit_path = f.unit_path
  FROM unit_fix f WHERE p.id = f.id AND p.unit_path = '{}';
  GET DIAGNOSTICS v_filled = ROW_COUNT;

  -- 4) 지문: 딸린 문항이 모두 한 단원이면(빈 문항 없이) 빈 지문 단원도 같은 값으로
  UPDATE passages pa SET unit_path = x.u
  FROM (
    SELECT p.passage_id, min(p.unit_path) AS u
    FROM problems p
    WHERE p.passage_id IN (SELECT p2.passage_id FROM problems p2 JOIN unit_fix f ON f.id = p2.id WHERE p2.passage_id IS NOT NULL)
    GROUP BY p.passage_id
    HAVING count(DISTINCT p.unit_path) = 1 AND bool_and(p.unit_path <> '{}')
  ) x
  WHERE pa.id = x.passage_id AND pa.unit_path = '{}';
  GET DIAGNOSTICS v_psg = ROW_COUNT;

  -- 5) 검증: 판정한 문항이 전부 판정값이거나(이번·전에 채움) 손으로 붙인 다른 값이다
  SELECT count(*) INTO v_bad FROM unit_fix f JOIN problems p ON p.id = f.id WHERE p.unit_path = '{}';
  IF v_bad > 0 THEN
    RAISE EXCEPTION '채우지 못한 문항 % 개', v_bad;
  END IF;

  RAISE NOTICE '판정 % 문항: 이번에 채움 % · 이미 같은 값 % · 다른 값이라 건너뜀 % · 지문 단원 채움 %',
    (SELECT count(*) FROM unit_fix), v_filled, v_same, v_other, v_psg;
END $units$;
